/* 1. Adaptive Card Resize */
.st-resize-card {
  --s-dur: 300ms;
  --s-ease: var(--ease-smooth-out);
  width: 232px;
  height: 112px;
  padding: 14px;
  border-radius: 16px;
  background: var(--ml-surface);
  border: 1px solid var(--ml-border);
  box-shadow: var(--ml-shadow-md);
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
  transition:
    width calc(var(--s-dur) * var(--ml-speed)) var(--s-ease),
    height calc(var(--s-dur) * var(--ml-speed)) var(--s-ease);
}

.st-resize-card.is-compact {
  width: 162px;
  height: 138px;
}

.st-resize-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12.5px;
