  height: 9px;
  border-radius: 99px;
  background: var(--ml-surface-subtle);
}

.st-bar.w80 { width: 80%; }
.st-bar.w60 { width: 60%; }
.st-bar.w92 { width: 92%; }
.st-bar.w45 { width: 45%; }

