/* 2. Origin-Aware Action Menu */
.st-menu-anchor {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 112px;
}

.st-menu-btn {
  height: 36px;
  padding: 0 14px;
  border-radius: 10px;
  border: 1px solid var(--ml-border-strong);
  background: var(--ml-surface);
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  box-shadow: var(--ml-shadow-sm);
}

.st-menu-pop {
  --s-open-dur: 250ms;
  --s-close-dur: 150ms;
  --s-pre-scale: 0.97;
  --s-close-scale: 0.99;
  --s-ease: var(--ease-smooth-out);
  position: absolute;
  top: 44px;
  width: 196px;
  padding: 6px;
  border-radius: 14px;
  background: var(--ml-surface);
  border: 1px solid var(--ml-border);
  box-shadow: var(--ml-shadow-lg);
  transform-origin: top center;
  opacity: 0;
  transform: translateY(-4px) scale(var(--s-pre-scale));
  pointer-events: none;
  transition:
    opacity calc(var(--s-close-dur) * var(--ml-speed)) var(--s-ease),
    transform calc(var(--s-close-dur) * var(--ml-speed)) var(--s-ease);
}

.st-menu-pop.is-open {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
  transition:
    opacity calc(var(--s-open-dur) * var(--ml-speed)) var(--s-ease),
    transform calc(var(--s-open-dur) * var(--ml-speed)) var(--s-ease);
}

.st-menu-pop.is-closing {
  opacity: 0;
  transform: translateY(-2px) scale(var(--s-close-scale));
}

.st-menu-item {
  width: 100%;
  border: 0;
  background: transparent;
  padding: 8px 10px;
  border-radius: 8px;
  text-align: left;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.st-menu-item:hover {
  background: var(--ml-surface-subtle);
}

.st-menu-item.is-selected {
  color: var(--ml-accent);
  font-weight: 600;
}

